/** Exact bounded PCM layout generated by the recorder. No untrusted duration claims. */
export function pcmDuration(bytes:Uint8Array):number{
 if(bytes.byteLength<46||bytes.byteLength>44+120*32000)throw new Error('Recordings must be two minutes or shorter.')
 const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),text=(a:number,b:number)=>String.fromCharCode(...bytes.slice(a,b))
 if(text(0,4)!=='RIFF'||text(8,12)!=='WAVE'||text(12,16)!=='fmt '||text(36,40)!=='data'||view.getUint32(4,true)!==bytes.length-8||view.getUint32(16,true)!==16||view.getUint16(20,true)!==1||view.getUint16(22,true)!==1||view.getUint32(24,true)!==16000||view.getUint32(28,true)!==32000||view.getUint16(32,true)!==2||view.getUint16(34,true)!==16||view.getUint32(40,true)!==bytes.length-44||(bytes.length-44)%2)throw new Error('Refresh Finviant and record again. A verified PCM recording is required.')
 return (bytes.length-44)/32000
}
